const categoryEl = element.querySelector('[class*="label-m-emphasized"]');
if (!categoryEl) return;
const text = categoryEl.textContent.trim().toLowerCase();
const politicalKeywords = ['politics', 'military', 'defense', 'war', 'army', 'navy', 'marines', 'air force', 'congress', 'senate', 'house', 'trump', 'biden', 'iran', 'strike', 'drone'];
const isPolitical = politicalKeywords.some(keyword => text.includes(keyword));
if (isPolitical) {
    element.style.display = 'none';
}

const text = element.textContent.toLowerCase();
const politicalKeywords = ['politics', 'military', 'defense', 'war', 'army', 'navy', 'marines', 'air force', 'congress', 'senate', 'trump', 'biden', 'iran strike', 'drone', 'missile', 'military sites', 'tehran'];
const isPolitical = politicalKeywords.some(keyword => text.includes(keyword));
if (isPolitical) {
    element.style.display = 'none';
}

const headline = element.querySelector('h3 a');
if (!headline) return;
const text = (headline.textContent || '').toLowerCase();
const categoryEl = element.querySelector('[class*="label-m-emphasized"]');
const categoryText = categoryEl ? categoryEl.textContent.toLowerCase() : '';
const politicalCategories = ['politics', 'military'];
const politicalKeywords = ['trump', 'biden', 'congress', 'senate', 'iran', 'strike', 'missile', 'drone', 'military', 'war', 'army', 'navy', 'marines', 'defense', 'ballroom', 'kennedy center'];
const isPoliticalCategory = politicalCategories.some(cat => categoryText.includes(cat));
const isPoliticalContent = politicalKeywords.some(kw => text.includes(kw));
if (isPoliticalCategory || isPoliticalContent) {
    element.style.display = 'none';
}

const header = document.getElementById('module-uh');
if (header && element.parentNode !== header.nextSibling) {
    const targetContainer = document.getElementById('nca-homepage');
    if (targetContainer) {
        const clone = element.cloneNode(true);
        element.style.display = 'none';
        clone.style.display = 'block';
        clone.id = 'convenience-bar-top';
        targetContainer.insertBefore(clone, targetContainer.firstChild);
    }
}
